export interface OfflineStoryArc {
  /** Atmosfera e estranhamento do primeiro minuto. */
  opening: string;
  /** Fragmento de memória do corpo atual, útil sem apagar a identidade do jogador. */
  bodyMemory: string;
  /** Primeira ampliação do caso, revelada quando a investigação deixa o incidente inicial. */
  phase1: string;
  phase1Clue: string;
  /** Duas versões possíveis da grande virada; o motor escolhe conforme a campanha. */
  phase2Trust: string;
  phase2Distrust: string;
  phase2ClueTrust: string;
  phase2ClueDistrust: string;
  /** Convergência para o ato final. */
  phase3: string;
  phase3Clue: string;
  /** Aviso diegético de que uma escolha específica pode ser fatal. */
  fatalWarning: string;
  /** Palavras/frases que tornam uma ação imprudente especialmente perigosa neste prólogo. */
  hazardTerms: string[];
  /** Cena-base usada quando a imprudência neste arco mata o personagem. */
  deathScene: string;
  /** Eco do caso inicial usado no epílogo, qualquer que seja o final. */
  epilogueEcho: string;
}

